window.ScripturaLexicons.BDAG_PART_0210 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0210-01\" data-source=\"BDAG\" data-search=\"κρέμαμαι verbo; remissão estar pendurado; depender; veja κρεμάννυμι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κρέμαμαι</td><td>verbo; remissão</td><td>estar pendurado; depender; veja κρεμάννυμι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0210-02\" data-source=\"BDAG\" data-search=\"κρεμάννυμι verbo pendurar; suspender; estar pendurado; depender BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κρεμάννυμι</td><td>verbo</td><td>pendurar; suspender; estar pendurado; depender</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0210-03\" data-source=\"BDAG\" data-search=\"κρεπάλη substantivo feminino; variante gráfica bebedeira; ressaca; veja κραιπάλη BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κρεπάλη</td><td>substantivo feminino; variante gráfica</td><td>bebedeira; ressaca; veja κραιπάλη</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0210-04\" data-source=\"BDAG\" data-search=\"κρημνός, οῦ, ὁ substantivo masculino precipício; barranco; encosta íngreme BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κρημνός, οῦ, ὁ</td><td>substantivo masculino</td><td>precipício; barranco; encosta íngreme</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0210-05\" data-source=\"BDAG\" data-search=\"κρημνώδης, ες adjetivo íngreme; escarpado; precipitoso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κρημνώδης, ες</td><td>adjetivo</td><td>íngreme; escarpado; precipitoso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0210-06\" data-source=\"BDAG\" data-search=\"Κρής, ητός, ὁ substantivo masculino; gentílico cretense; habitante de Creta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κρής, ητός, ὁ</td><td>substantivo masculino; gentílico</td><td>cretense; habitante de Creta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0210-07\" data-source=\"BDAG\" data-search=\"Κρήσκης, εντος, ὁ nome próprio masculino Crescente; companheiro de Paulo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κρήσκης, εντος, ὁ</td><td>nome próprio masculino</td><td>Crescente; companheiro de Paulo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0210-08\" data-source=\"BDAG\" data-search=\"Κρήτη, ης, ἡ nome próprio feminino; topônimo Creta; ilha do mar Mediterrâneo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κρήτη, ης, ἡ</td><td>nome próprio feminino; topônimo</td><td>Creta; ilha do mar Mediterrâneo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0210-09\" data-source=\"BDAG\" data-search=\"κριθή, ῆς, ἡ substantivo feminino cevada; grão usado para pães baratos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κριθή, ῆς, ἡ</td><td>substantivo feminino</td><td>cevada; grão usado para pães baratos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0210-10\" data-source=\"BDAG\" data-search=\"κρίθινος, η, ον adjetivo feito de farinha de cevada; de cevada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κρίθινος, η, ον</td><td>adjetivo</td><td>feito de farinha de cevada; de cevada</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0210-11\" data-source=\"BDAG\" data-search=\"κρίκος, ου, ὁ substantivo masculino anel; aro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κρίκος, ου, ὁ</td><td>substantivo masculino</td><td>anel; aro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0210-12\" data-source=\"BDAG\" data-search=\"κρίμα, ατος, τό substantivo neutro processo; decisão; julgamento; sentença condenatória; justiça BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κρίμα, ατος, τό</td><td>substantivo neutro</td><td>processo; decisão; julgamento; sentença condenatória; justiça</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0210-13\" data-source=\"BDAG\" data-search=\"κρίνον, ου, τό substantivo neutro lírio; flor campestre de identificação incerta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κρίνον, ου, τό</td><td>substantivo neutro</td><td>lírio; flor campestre de identificação incerta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0210-14\" data-source=\"BDAG\" data-search=\"κρίνω verbo selecionar; julgar; decidir; processar; condenar; fazer justiça BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κρίνω</td><td>verbo</td><td>selecionar; julgar; decidir; processar; condenar; fazer justiça</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0210-15\" data-source=\"BDAG\" data-search=\"κριός, οῦ, ὁ substantivo masculino carneiro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κριός, οῦ, ὁ</td><td>substantivo masculino</td><td>carneiro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0210-16\" data-source=\"BDAG\" data-search=\"κρίσις, εως, ἡ substantivo feminino julgamento; condenação; tribunal; justiça BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κρίσις, εως, ἡ</td><td>substantivo feminino</td><td>julgamento; condenação; tribunal; justiça</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0210-17\" data-source=\"BDAG\" data-search=\"κρίσμα remissão lexical veja κρίμα BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κρίσμα</td><td>remissão lexical</td><td>veja κρίμα</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0210-18\" data-source=\"BDAG\" data-search=\"Κρίσπος, ου, ὁ nome próprio masculino Crispo; dirigente de sinagoga em Corinto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κρίσπος, ου, ὁ</td><td>nome próprio masculino</td><td>Crispo; dirigente de sinagoga em Corinto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0210-19\" data-source=\"BDAG\" data-search=\"κριτήριον, ου, τό substantivo neutro tribunal; foro; processo judicial BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κριτήριον, ου, τό</td><td>substantivo neutro</td><td>tribunal; foro; processo judicial</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0210-20\" data-source=\"BDAG\" data-search=\"κριτής, οῦ, ὁ substantivo masculino juiz; julgador; governante de Israel BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κριτής, οῦ, ὁ</td><td>substantivo masculino</td><td>juiz; julgador; governante de Israel</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0210-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρέμαμαι</h1><div class=\"entry-meta\"><span>verbo; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κρέμαμαι</span>: veja <span class=\"greek\">κρεμάννυμι</span> 2.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0210-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρεμάννυμι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κρεμάννυμι</span> (esta forma de presente não ocorre na Bíblia grega, mas Job 26:7 traz <span class=\"greek\">κρεμάζω</span>. A palavra, nas acepções 1 e 2, ocorre desde Hom. e outros; inscrições, papiros, LXX, TestSol, TestAbr; TestLevi 2:7; JosAs 22:5; ParJer; GrBar 9:8; ApcMos 17; ApcrEzk P 2 verso 10; Philo; Jos., Vi. 147 e outras passagens): futuro <span class=\"greek\">κρεμάσω</span>, LXX; 1º aoristo <span class=\"greek\">ἐκρέμασα</span>; passiva <span class=\"greek\">ἐκρεμάσθην</span>.</p>\n<p class=\"entry-text\">① Fazer com que algo fique suspenso, transitivo: pendurar, suspender; <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ξύλου</span>, sobre a madeira, isto é, na cruz (compare Gen 40:19; Dt 21:22; Esth 8:7), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:30</a>; 10:39. O verbo <span class=\"greek\">κ</span>. por si só também pode significar crucificar (Diod S 17, 46, 4; Appian, Mithrid. 8 §25; 29 §114 <span class=\"greek\">δούλους</span> <span class=\"greek\">ἐκρέμασε</span>; Bell. Civ. 2, 90 §377; Arrian, Anab. 6, 17, 2; 6, 30, 2; 7, 14, 4). Na passiva, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:39</a> (compare Appian, Bell. Civ. 3, 3 §9; Sb 6739 [255 a.C.], 9).—<span class=\"greek\">ἵνα</span> <span class=\"greek\">κρεμασθῇ</span> <span class=\"greek\">μύλος</span> <span class=\"greek\">ὀνικὸς</span> <span class=\"greek\">περὶ</span> (variantes de leitura <span class=\"greek\">εἰς</span>, <span class=\"greek\">ἐπί</span>, <span class=\"greek\">ἐν</span> [<span class=\"greek\">τῷ</span>-<span class=\"greek\">λῷ</span>]) <span class=\"greek\">τὸν</span> <span class=\"greek\">τράχηλον</span> <span class=\"greek\">αὐτοῦ</span>, que uma pedra de moinho movido por jumento fosse pendurada ao redor do pescoço dessa pessoa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:6</a>. Reflexivamente: <span class=\"greek\">ἐκρέμασεν</span> <span class=\"greek\">ἁτὴν</span> (=<span class=\"greek\">αὑτὴν</span>) <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τράχηλον</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">Ἅννα</span>, Ana pendurou-se ao pescoço dele, GJs 4:4 (compare TestAbr A 5 p. 82, 19 [Stone p. 12] <span class=\"greek\">ἐκρεμάσθη</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τράχηλον</span> <span class=\"greek\">αὐτοῦ</span>; igualmente JosAs 22:5).—1 Cl 12:7, variante de leitura, Funk.</p>\n<p class=\"entry-text\">② Depoente <span class=\"greek\">κρέμαμαι</span> (veja B-D-F §93; Rob. 316f): ficar pendurado a partir de certo ponto; intransitivo, pender. ⓐ Literalmente (TestSol 24:4; recensão D 6:14; TestLevi 2:7; GrBar 9:8; ApcEsdr 4:22 p. 28, 25 Tdf. e outros; Jos., Ant. 7, 241): <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινος</span>, em alguma coisa (X., An. 3, 2, 19); <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ξύλου</span> (veja 1 acima), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:13</a> (Dt 21:23). De ramo de videira: <span class=\"greek\">μὴ</span> <span class=\"greek\">κρεμαμένη</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πτελέας</span>, caso não esteja pendurado no olmo, Hs 2:3; compare o v. 4. <span class=\"greek\">ἔκ</span> <span class=\"greek\">τινος</span>, de alguma coisa (Pla., Leg. 8, 831c; SIG2 588, 201; compare Jdth 8:24); de uma serpente: <span class=\"greek\">κ</span>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">χειρός</span>, pendia da mão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:4</a>. Dos castigados no inferno: <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γλώσσης</span> <span class=\"greek\">κρεμάμενοι</span>, pendurados pela língua, ApcPt 7:22 (compare ApcEsdr 4:22 p. 28, 25 Tdf. <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">βλεφάρων</span>).</p>\n<p class=\"entry-text\">ⓑ Figuradamente (Philo, Post. Cai. 24; 25; SibOr 7, 55): <span class=\"greek\">ἐν</span> <span class=\"greek\">ταύταις</span> <span class=\"greek\">τ</span>. <span class=\"greek\">δυσὶν</span> <span class=\"greek\">ἐντολαῖς</span> <span class=\"greek\">ὅλος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">νόμος</span> <span class=\"greek\">κρέμαται</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">προφῆται</span>, toda a Lei e os Profetas dependem destes dois mandamentos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:40</a> (assim como uma porta pende de suas dobradiças, assim também todo o AT depende destes dois mandamentos. Quanto ao pensamento, compare Plut., Mor. 116d.—Sobre <span class=\"greek\">κ</span>. <span class=\"greek\">ἐν</span>, compare 2 Km 18:9; Billerb. I 775ff; 967f).—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0210-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρεπάλη</h1><div class=\"entry-meta\"><span>substantivo feminino; variante gráfica</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κρεπάλη</span> (veja Mlt-H. 81): em lugar de <span class=\"greek\">κραιπάλη</span> (veja essa entrada). Contudo, Aristoph., Ach. 277, Wasps 1255 comprovam a duração longa da primeira sílaba.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0210-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρημνός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κρημνός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (veja o próximo verbete; Hom. e outros; Kaibel 225, 2; PPetr III, 39 II, 8; 2 Ch 25:12; TestSol, TestAbr, Test12Patr; EpArist 118; Jos., Ant. 3, 76): encosta ou barranco íngreme, precipício; <span class=\"greek\">κατὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κ</span>., encosta abaixo (Dio Chrys. 7, 3; Philo, Agr. 76; Jos., Bell. 1, 313), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:33</a>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">μεγάλου</span>, de um grande precipício, ApcPt 17:32 (<span class=\"greek\">ἀπὸ</span> <span class=\"greek\">κ</span>., como Celsus 6, 34).—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0210-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρημνώδης, ες</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κρημνώδης</span>, <span class=\"greek\">ες</span> (<span class=\"greek\">κρημνός</span> ±<span class=\"greek\">ώδης</span>; veja o verbete precedente; desde Thu. 7, 84, 4; Jos., Bell. 7, 280): íngreme, escarpado; <span class=\"greek\">ἦν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τόπος</span> <span class=\"greek\">κ</span>., o lugar era escarpado (Stephan. Byz. s.v. <span class=\"greek\">Ὄαξος</span>: <span class=\"greek\">τὸν</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">κρημνώδη</span> <span class=\"greek\">ὑπάρχειν</span>), Hv 1, 1, 3; compare Hs 6, 2, 6.—DELG s.v. <span class=\"greek\">κρημνός</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0210-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κρής, ητός, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino; gentílico</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Κρής</span>, <span class=\"greek\">ητός</span>, <span class=\"greek\">ὁ</span>; plural <span class=\"greek\">Κρῆτες</span> (desde Hom.; inscrições; UPZ 20, 32 [163 a.C.]; 29, 2; Jos., Ant. 13, 86, C. Ap. 2, 172; Tat.; SibOr 3, 140): cretense, habitante da ilha de Creta, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:11</a> (OEissfeldt, Kreter u. Araber: TLZ 72, ’47, 207–12); subscrição de Tit, variante de leitura. Uma generalização desfavorável acerca do caráter dos cretenses (veja sobre isso <span class=\"greek\">ἀργός</span> 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:12</a>.—RHarris, Exp. 2, 1906, 305–17; 3, 1907, 332–37; 4, 1912, 348–53; 1, 1915, 29–35; MGöbel, Ethnica, dissertação, Breslau 1915, 77ff; RCharles, Anthropologie arch. de la Crète, ’65.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0210-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κρήσκης, εντος, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Κρήσκης</span>, <span class=\"greek\">εντος</span>, <span class=\"greek\">ὁ</span> (latim Crescens; a forma grega é bastante rara [<span class=\"greek\">Κρί</span>-Just., A II, 3, 1; Tat. 19, 1], enquanto a latina é comum, incluindo Pol 14, preservada apenas em latim): Crescente, companheiro de Paulo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:10</a>. Veja <span class=\"greek\">Κρίσπος</span>. New Docs 3, 91.—LGPN I.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0210-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κρήτη, ης, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino; topônimo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Κρήτη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (Hom. e outros; inscrições; 1 Macc 10:67; Philo, Spec. Leg. 3, 43; Joseph.; Tat. 39, 3; SibOr): Creta, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:7</a>, 12f, 21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:5</a>; subscrição, variante de leitura (já em Il. 2, 649 Creta era famosa por suas numerosas cidades; Ps.-Scylax [edição de BFabricius 1878] apresenta os nomes de muitas cidades).—LCottrell, The Bull of Minos ’53; RWilletts, Everday Life in Ancient Crete ’69; Warnecke, Romfahrt 21–28.—OEANE II 70–72. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0210-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κριθή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κριθή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (veja o verbete seguinte; desde Hom., mas no grego antigo somente no plural. Em contrapartida, entre autores posteriores [Dionys. Hal. 2, 25; Cornutus 28 p. 54, 4; Libanius, De Vita Sua 8 Förster, variante de leitura; Herm. Wr. 14, 10; Philo, Spec. Leg. 2, 175; 3, 57; Jos., Bell. 5, 427], em inscrições, papiros e LXX também no singular): cevada, empregada no preparo de tipos baratos de pão (veja Hdb. sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:9</a>; Appian, Illyr. 26 §76 <span class=\"greek\">κριθὴ</span> <span class=\"greek\">ἀντὶ</span> <span class=\"greek\">σίτου</span>, para soldados de categoria inferior). <span class=\"greek\">τρεῖς</span> <span class=\"greek\">χοίνικες</span> <span class=\"greek\">κριθῶν</span>, três litros ou quartos de cevada (texto recebido <span class=\"greek\">κριθῆς</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:6</a> (veja <span class=\"greek\">χοῖνιξ</span>); GDalman, Arbeit II ’32, 252f; III ’33, 300ff.—B. 516. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0210-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρίθινος, η, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κρίθινος</span>, <span class=\"greek\">η</span>, <span class=\"greek\">ον</span> (veja o verbete precedente; desde Hipponax [VI a.C.] 39, 6 Diehl; PEleph 5, 25 [284/283 a.C.]; BGU 1092, 28; LXX; Philo, Spec. Leg. 2, 175; Jos., Ant. 5, 219): feito de farinha de cevada; <span class=\"greek\">ἄρτος</span> <span class=\"greek\">κ</span>., pão de cevada (Plut., Anton. 45, 8; Artem. 1, 69; sobretudo 4 Km 4:42), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:9</a>, 13.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0210-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρίκος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κρίκος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (desde Hom.; inscrições, papiros, LXX; Jos., Ant. 3, 109f; 136): anel, aro; <span class=\"greek\">κάμπτειν</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">κρίκον</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τράχηλον</span>, curvar o pescoço como um anel, isto é, de modo que fique tão arredondado quanto um anel, B 3:2 (Is 58:5).—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0210-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρίμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κρίμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (veja <span class=\"greek\">κρίνω</span>; desde Aeschyl.—Sobre a acentuação, veja B-D-F §13; 109, 3; W-S. §6, 3; Mlt-H. 57; <span class=\"greek\">κρίσμα</span> GJs 14:1).</p>\n<p class=\"entry-text\">① Ação judicial movida contra alguém; disputa, demanda judicial (Ex 18:22): <span class=\"greek\">κρίματα</span> <span class=\"greek\">ἔχετε</span> <span class=\"greek\">μεθ</span>’ <span class=\"greek\">ἑαυτῶν</span>, tendes demandas judiciais uns contra os outros, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:7</a>.</p>\n<p class=\"entry-text\">② Conteúdo de um processo deliberativo; decisão, decreto (IGal 25, 2 [II d.C.] <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">βουλῆς</span>; Ps 18:10; 118:75; Jos., Ant. 14, 318; 321; ParJer 7:32 [28]; Did., Gen. 116, 24), também dos propósitos firmes da graça divina, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:33</a>.</p>\n<p class=\"entry-text\">③ Ação ou função de um juiz; ato de julgar, julgamento: <span class=\"greek\">κρίμα</span> <span class=\"greek\">ἐδόθη</span> <span class=\"greek\">αὐτοῖς</span>, foi-lhes dada autoridade para julgar, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.20.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 20:4</a>.—Acerca do julgamento divino: <span class=\"greek\">τὸ</span> <span class=\"greek\">κρίμα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μέλλον</span>, o juízo futuro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:25</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">αἰώνιον</span>, julgamento cuja decisão vigora eternamente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:2</a>. O julgamento de Deus começa com seu povo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:17</a>. No plural, Deus é <span class=\"greek\">δίκαιος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">κρίμασιν</span>, justo em seus juízos, 1 Cl 27:1; 60:1.—O uso indevido da autoridade de julgar é criticado em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:1</a>, variante de leitura.</p>\n<p class=\"entry-text\">④ Decisão legal proferida por juiz; sentença judicial. ⓐ Em geral (Polyb. 23, 1, 12): <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἑνὸς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">κατάκριμα</span>, a sentença resultou de uma única transgressão e levou à punição, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:16</a>.</p>\n<p class=\"entry-text\">ⓑ Predominantemente em sentido desfavorável, sentença condenatória, às vezes também a própria punição subsequente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Jd 4</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, a condenação de Deus (isto é, pronunciada por Deus), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:2f</a>. <span class=\"greek\">ὧν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἔνδικόν</span> <span class=\"greek\">ἐστιν</span>, a condenação deles é justa, 3:8 (mas WFitch, ET 59, ’47/48, 26, prefere ‘veredicto’). <span class=\"greek\">πρόδηλον</span> <span class=\"greek\">ἐγενήθη</span>, a condenação deles se tornou manifesta, 1 Cl 51:3. <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">πόρνης</span>, condenação e castigo da prostituta, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 17:1</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">συνέρχεσθαι</span>, reunir-se para condenação, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.34\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:34</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">ἑαυτῷ</span> <span class=\"greek\">ἐσθίειν</span>, comer a própria condenação, v. 29; <span class=\"greek\">λαμβάνεσθαι</span> <span class=\"greek\">κ</span>., ser condenado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:13</a>, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:40</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:47</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:1</a>. <span class=\"greek\">ἔχουσαι</span> <span class=\"greek\">κ</span>., <span class=\"greek\">ὅτι</span>, estão sujeitas à condenação porque, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:12</a>; <span class=\"greek\">βαστάζειν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>., levar a condenação, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:10</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">γίνεσθαι</span>, incorrer em condenação, 1 Cl 11:2. <span class=\"greek\">εἰς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">γίνεσθαί</span> <span class=\"greek\">τινι</span>, tornar-se motivo de condenação para alguém, 21:1; IEph 11:1 (compare TestJob 43:6 <span class=\"greek\">ἀποβήσετα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">κ</span>.). <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">εἶναι</span>, estar sob a mesma condenação, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:40</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐμπίπτειν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">διαβόλου</span>, incorrer na condenação do diabo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:6</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">θανάτου</span> (compare Dt 21:22; Sir 41:3), sentença de morte, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:20</a>; GJs 14:1 (<span class=\"greek\">τοῦ</span> <span class=\"greek\">θανάτου</span>, papiro [?], veja deStrycker p. 236).—No plural (compare BGU 471, 9 [II d.C.]): <span class=\"greek\">τὰ</span> <span class=\"greek\">μέλλοντα</span> <span class=\"greek\">κρίματα</span>, as punições iminentes, 1 Cl 28:1. Sobre 1 Cl 20:5 veja <span class=\"greek\">ἀνεκδιήγητος</span>.—GWetter, Der Vergeltungsgedanke bei Pls 1912, 1ff.—O AT é a fonte da expressão <span class=\"greek\">κρίνειν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. (compare Zech 7:9; 8:16; Ezk 44:24): <span class=\"greek\">ἔκρινεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κρίμα</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">αὐτῆς</span>, Deus pronunciou sentença em vosso favor contra ela, ou Deus pronunciou contra ela a sentença que ela pretendia impor a vós (HHoltzmann, Hdb. 1893 ad loc.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:20</a>.</p>\n<p class=\"entry-text\">⑤ Reconhecimento adequado dos direitos de alguém; justiça. O AT é a origem da estreita associação entre <span class=\"greek\">κ</span>. e <span class=\"greek\">δικαιοσύνη</span> e da expressão <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">δικαιοσύνην</span> (Jer 23:5; Ezk 33:14), praticar justiça e retidão, 1 Cl 13:1.</p>\n<p class=\"entry-text\">⑥ Em J, <span class=\"greek\">κ</span>. apresenta a mesma duplicidade de sentido dos demais membros da família de <span class=\"greek\">κρίνω</span> (‘julgamento’ e ‘separação’; veja Hdb. sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:17</a>) e designa a decisão judicial que consiste na separação entre os que estão dispostos a crer e os que se recusam a fazê-lo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.39\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:39</a>.—B. 1422. DELG s.v. <span class=\"greek\">κρίνω</span>. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0210-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρίνον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κρίνον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Aristoph., Hdt. e outros; Longus 2, 3, 4 [<span class=\"greek\">ῥόδα</span>, <span class=\"greek\">κρίνα</span>, <span class=\"greek\">ὑάκινθος</span>, como flores primaveris]; Kaibel 547, 1 [I d.C.]; PSI 297, 8; Stephan. Byz. s.v. <span class=\"greek\">Σοῦσα</span> [a região ao redor de Susa é abundante em <span class=\"greek\">κρίνα</span>]; LXX; EpArist 68; 75; compare Jos., Ant. 8, 77; TestSim 6:2; empréstimo no hebraico rabínico): lírio. Nesse contexto, as principais opiniões incluem o cólquico-do-outono, o lírio-turbante, a anêmona ou o gladíolo, mas os dados não permitem certeza. Talvez Jesus não tivesse em mente uma flor determinada, mas pensasse em todas as esplêndidas flores que adornam os campos da Galileia. Como flor de beleza extraordinária (como Theodor. Prodr. 6, 296 H.), é mencionada em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:27</a>.—LFonck, Streifzüge durch die biblische Flora 1900, 53ff; JBoehmer, Die Lilien auf dem Felde: Studierstube 6, 1908, 223ff; FLundgreen, Die Pflanzen im NT: NKZ 28, 1917, 828ff; GDalman, Die Lilie der Bibel: PJ 21, 1925, 98ff, Arbeit I, 1928, 357ff e outras passagens; ILöw, D. Flora d. Juden II 1924, 160ff, também IV ’34, 669 (índices); GKing, Consider the Lilies: Crozer Quarterly 10, ’33, 28–36; TSkeat, The Lilies of the Field: ZNW 37, ’39, 211–14; M. et Mme. EHa-Reubeni, RB 54, ’47, 362–64 (anthemis ou margarida-da-Páscoa, francês pâquerette); Zohary, Plants 169–71.—Pauly-W. VII 792ff; Kl. Pauly III 650f; BHHW II 1093.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0210-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρίνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κρίνω</span> (veja <span class=\"greek\">κρίμα</span>; desde Hom.): futuro <span class=\"greek\">κρινῶ</span>; 1º aoristo <span class=\"greek\">ἔκρινα</span>; perfeito <span class=\"greek\">κέκρικα</span>; mais-que-perfeito, 3ª pessoa do singular, <span class=\"greek\">κεκρίκει</span> (quanto à falta de aumento, veja B-D-F §66, 1; W-S. §12, 4; Mlt-H. 190; <span class=\"greek\">ἐκεκρίκει</span> Just., D. 102, 2). Na passiva: imperfeito <span class=\"greek\">ἐκρινόμην</span>; 1º futuro <span class=\"greek\">κριθήσομαι</span>; 1º aoristo <span class=\"greek\">ἐκρίθην</span>; perfeito <span class=\"greek\">κέκριμαι</span>. Significado primário: ‘separar para distinguir, apartar’; depois, por transferência:</p>\n<p class=\"entry-text\">① Fazer uma escolha; escolher, preferir (Aeschyl., Suppl. 39 <span class=\"greek\">τὶ</span>; Pla., Rep. 3, 399e <span class=\"greek\">κρίνειν</span> <span class=\"greek\">τινὰ</span> <span class=\"greek\">πρό</span> <span class=\"greek\">τινος</span>, ‘preferir alguém a outrem’, compare Phlb. 57e; Himerius, Or. 40 [=Or. 6], 3 <span class=\"greek\">κ</span>. <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span>, escolher algo por causa de outra coisa [um lugar por sua extensão]; <span class=\"greek\">κ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">πρακτέον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">πρακτέον</span>, decidir o que deve ou não ser feito, Did., Gen. 27, 3): <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">κρίνει</span> <span class=\"greek\">ἡμέραν</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ἡμέραν</span>, pois um prefere um dia a outro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:5a</a>. Na segunda metade da frase, <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">κρίνει</span> <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">ἡμέραν</span>, <span class=\"greek\">κ</span>. provavelmente significa reconhecer, aprovar (X., Hell. 1, 7, 34 <span class=\"greek\">ἔκριναν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">βουλῆς</span> <span class=\"greek\">γνώμην</span>), o outro estima todos os dias, v. 5b. Intimamente associado encontra-se o sentido</p>\n<p class=\"entry-text\">② Proferir juízo sobre a vida e as ações de outras pessoas (e, assim, procurar influenciá-las). ⓐ Julgar, emitir juízo, expressar uma opinião sobre, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:1a</a>, 2a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:37a</a>; 1 Cl 13:2; Pol 2:3 (Sextus 183 <span class=\"greek\">ὁ</span> <span class=\"greek\">κρίνων</span> <span class=\"greek\">ἄνθρωπον</span> <span class=\"greek\">κρίνεται</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span>). <span class=\"greek\">κ</span>. <span class=\"greek\">δικαίως</span>, julgar justamente, D 4:3; B 19:11. <span class=\"greek\">κ</span>. <span class=\"greek\">κατ</span>’ <span class=\"greek\">ὄψιν</span>, pela aparência exterior, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:24a</a>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σάρκα</span>, segundo a carne, 8:15. <span class=\"greek\">τὴν</span> <span class=\"greek\">δικαίαν</span> <span class=\"greek\">κρίσιν</span> <span class=\"greek\">κ</span>., proferir um juízo justo, 7:24b (sobre a expressão, compare Dt 16:18). Talvez pertença aqui <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:6</a> <span class=\"greek\">ἵνα</span> <span class=\"greek\">κριθῶσιν</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">ἀνθρ</span>. (veja ESelwyn, comentário ad loc., com referência a Lghtf.; compare Wsd 3:4).</p>\n<p class=\"entry-text\">ⓑ Especialmente, proferir juízo desfavorável, criticar, censurar, condenar (Epict. 2, 21, 11), Ro 2:1abc, 3; 14:3f, 10, 13a (jogo de palavras em que <span class=\"greek\">κρίνειν</span> é empregado em dois sentidos no mesmo versículo; veja 4 abaixo, sobre o v. 13b); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:11</a>, 12; D 11:12. <span class=\"greek\">μή</span> <span class=\"greek\">τι</span> <span class=\"greek\">κρίνετε</span>, não julgueis coisa alguma, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:5</a>. <span class=\"greek\">ἱνατί</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐλευθερία</span> <span class=\"greek\">μου</span> <span class=\"greek\">κρίνεται</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">ἄλλης</span> <span class=\"greek\">συνειδήσεως</span>;, por que minha liberdade de ação é julgada desfavoravelmente pelos escrúpulos de outra pessoa?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.29\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:29</a>. <span class=\"greek\">μακάριος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">κρίνων</span> <span class=\"greek\">ἑαυτόν</span>, feliz aquele que não encontra motivo de censura em si mesmo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:22</a>.—Também sobre juízo humano dirigido contra Deus: <span class=\"greek\">ὅπως</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">νικήσεις</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κρίνεσθαί</span> <span class=\"greek\">σε</span>, para que venças quando fores julgado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:4</a> (OMichel, em KEK, prefere o sentido ativo); 1 Cl 18:4 (ambos em Ps 50:6).</p>\n<p class=\"entry-text\">③ Formular uma avaliação levando em conta diversos fatores; julgar, pensar, considerar, reputar, com duplo acusativo de objeto e predicativo (Soph., Oed. R. 34; Pla., Rep. 9, 578b e veja Cebes 39, 4; 3 Macc 2:33; Just., D. 112, 1): <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀξίους</span> <span class=\"greek\">κρίνετε</span> <span class=\"greek\">ἑαυτούς</span>, não vos considerais dignos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.46\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:46</a> (Jos., Ant. 6, 159 <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">αὐτὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">βασιλείας</span> <span class=\"greek\">ἄξιον</span> <span class=\"greek\">ἔκρινεν</span>; EpArist 98); compare PtK 3 p. 15, 17. <span class=\"greek\">τὰ</span> <span class=\"greek\">ὑστερήματα</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">ἴδια</span> <span class=\"greek\">ἐκρίνετε</span>, considerastes como vossas as carências deles, 1 Cl 2:6. Na passiva (Thu. 2, 40, 3; Jos., Ant. 4, 193): <span class=\"greek\">τί</span> <span class=\"greek\">ἄπιστον</span> <span class=\"greek\">κρίνεται</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ὑμῖν</span>;, por que é considerado incrível entre vós?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:8</a> (Jos., Ant. 18, 76 <span class=\"greek\">ἄπιστα</span> <span class=\"greek\">αὐτὰ</span> <span class=\"greek\">κρίνειν</span>).—Seguido de acusativo com infinitivo (Pla., Gorg., 452c, Rep. 9, 578b; X., An. 1, 9, 5; 28): <span class=\"greek\">κεκρίκατέ</span> <span class=\"greek\">με</span> <span class=\"greek\">πιστὴν</span> … <span class=\"greek\">εἶναι</span>, vós me considerastes fiel, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:15</a>.—Seguido de infinitivo: <span class=\"greek\">κρίνω</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">παρενοχλεῖν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">κτλ</span>., decido não importunar os etc., 15:19.—Seguido de <span class=\"greek\">τοῦτο</span> <span class=\"greek\">ὅτι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:14</a>.—Seguido de pergunta direta: <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">κρίνατε</span>, julgai e decidi por vós mesmos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:13</a>.—Seguido de pergunta indireta (Thu. 4, 130, 7 <span class=\"greek\">κρίναντες</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σφίσιν</span> <span class=\"greek\">αὐτοῖς</span>, <span class=\"greek\">εἰ</span> … ; X., Cyr. 4, 1, 5): <span class=\"greek\">εἰ</span> <span class=\"greek\">δίκαιόν</span> <span class=\"greek\">ἐστιν</span>, <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἀκούειν</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, <span class=\"greek\">κρίνατε</span>, julgai se é justo obedecer mais a vós do que a Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:19</a>.—<span class=\"greek\">κρίνατε</span> <span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">ὅ</span> <span class=\"greek\">φημι</span>, julgai vós mesmos o que digo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:15</a>.—<span class=\"greek\">ὀρθῶς</span> <span class=\"greek\">ἔκρινας</span>, julgaste corretamente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:43</a>.</p>\n<p class=\"entry-text\">④ Chegar a uma conclusão depois de um processo cognitivo; decidir, determinar, propor-se, pretender (Isocr. 4, 46; Polyb. 3, 6, 7; 5, 52, 6; 9, 13, 7; Epict. 2, 15, 7; Appian, Bell. Civ. 14, 118 §497 <span class=\"greek\">ὅταν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">θεοὶ</span> <span class=\"greek\">κρίνωσιν</span>; LXX): <span class=\"greek\">τί</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">θέλετε</span>, <span class=\"greek\">κρίνατε</span> (texto restaurado), decidi, portanto, agora o que desejais (que se faça); seguido de infinitivo (Diod S 4, 33, 10; 17, 95, 1; UPZ 42, 37 [162 a.C.]; PTebt 55, 4 [II a.C.] <span class=\"greek\">ἔκρινα</span> <span class=\"greek\">γράψαι</span>; PLond III, 897, 11 p. 207 [84 d.C.]; 1 Macc 11:33; 3 Macc 1:6; Jdth 11:13; Wsd 8:9; Jos., Ant.7, 33; 12, 403; 13, 188; Did., Gen. 179, 7), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:13</a>; 20:16; 25:25; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:2</a>; 5:3; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:12</a>. Com <span class=\"greek\">τοῦ</span> e infinitivo (B-D-F §397, 2): <span class=\"greek\">ἐκρίθη</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀποπλεῖν</span> <span class=\"greek\">ἡμᾶς</span>, foi decidido que partiríamos de navio, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:1</a>. <span class=\"greek\">ἐπεὶ</span> <span class=\"greek\">ἤδη</span> <span class=\"greek\">σεαυτῷ</span> <span class=\"greek\">κέκρικας</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">δύνασθαι</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἐντολὰς</span> <span class=\"greek\">ταύτας</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">ἀνθρώπου</span> <span class=\"greek\">φυλαχθῆναι</span>, visto que já decidiste em tua própria mente que esses mandamentos não podem ser guardados por ser humano algum, Hm 12, 3, 6.—Com acusativo e infinitivo (2 Macc 11:25, 36; 3 Macc 6:30; TestSol 10:8; SibOr 3, 127; Just., D. 102, 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:25</a> (mesmo nas leituras substancialmente diferentes). <span class=\"greek\">τοῦτο</span> <span class=\"greek\">κέκρικεν</span> …, <span class=\"greek\">τηρεῖν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἑαυτοῦ</span> <span class=\"greek\">παρθένον</span>, decidiu isto, a saber, preservar sua noiva (pura e imaculada), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.37\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:37</a> (veja s.v. <span class=\"greek\">γαμίζω</span> 2; Diod S 4, 73, 2, de um pai: <span class=\"greek\">κρίναι</span> <span class=\"greek\">ταύτην</span> [isto é, a filha dele] <span class=\"greek\">παρθένον</span> <span class=\"greek\">διαφυλάττειν</span>). <span class=\"greek\">τοῦτο</span> <span class=\"greek\">κρίνατε</span> <span class=\"greek\">μᾶλλον</span>, <span class=\"greek\">τὸ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">τιθέναι</span> <span class=\"greek\">πρόσκομμα</span>, decidi antes isto: não pôr tropeço, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:13b</a>. <span class=\"greek\">ἔκρινα</span> <span class=\"greek\">ἐμαυτῷ</span> <span class=\"greek\">τοῦτο</span>, <span class=\"greek\">τὸ</span> … <span class=\"greek\">ἐλθεῖν</span>, decidi comigo mesmo isto, a saber, vir, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:1</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">δόγματα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">κεκριμένα</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀποστόλων</span>, as determinações decididas pelos apóstolos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:4</a> (compare Polyb. 5, 52, 6 <span class=\"greek\">πράξας</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κριθέν</span>; Epict. 2, 15, 7 <span class=\"greek\">τοῖς</span> <span class=\"greek\">κριθεῖσιν</span> <span class=\"greek\">ἐμμένειν</span> <span class=\"greek\">δεῖ</span>).</p>\n<p class=\"entry-text\">⑤ Participar de um processo judicial; julgar, decidir, levar perante um tribunal, condenar, também entregar para punição judicial, frequentemente como termo técnico jurídico (em sentido forense, desde Hom.; inscrições, papiros, LXX).</p>\n<p class=\"entry-text\">ⓐ De um tribunal humano. <span class=\"greek\">α</span>. Na voz ativa e passiva, absolutamente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:27</a>. Com advérbio, GPt 3:7. <span class=\"greek\">κ</span>. <span class=\"greek\">τινά</span>, julgar alguém: <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">νόμον</span>, segundo a lei, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.31\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:3</a>; 24:6, variante de leitura. <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">κρίνω</span> <span class=\"greek\">ὑμᾶς</span>, nem eu vos julgo, GJs 16:3. Sobre o direito do apóstolo e da igreja de julgar os crentes, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:12ab</a>. <span class=\"greek\">μὴ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">νόμος</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">κρίνει</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἄνθρωπον</span>;, por acaso nossa lei (personificada) julga uma pessoa?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.51\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:51</a> (Appian, Bell. Civ. 3, 50 §205: certos senadores desejam que, antes de Marco Antônio ser declarado inimigo público, seja submetido a julgamento, <span class=\"greek\">ὡς</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">πάτριον</span> <span class=\"greek\">σφίσιν</span> <span class=\"greek\">ἀκρίτου</span> <span class=\"greek\">καταδικάζειν</span>, ‘porque não era costume ancestral condenar alguém sem audiência’). <span class=\"greek\">ἐκ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">στόματός</span> <span class=\"greek\">σου</span> <span class=\"greek\">κρινῶ</span> <span class=\"greek\">σε</span>, eu te condenarei com base na tua própria declaração, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:22</a>. Na passiva, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:10</a>. <span class=\"greek\">κρίνεσθαι</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span>, ser levado a julgamento por alguma coisa, 26:6 (Appian, Basil. 12 <span class=\"greek\">κρινόμενος</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῷδε</span>, ser levado a julgamento por este motivo; igualmente Iber. 55 §233; Ath. 2, 3; de Deus, ApcrEzk Fgm. d). Também <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> (Diod S 12, 30, 5), 23:6; 25:20; com acréscimo de <span class=\"greek\">ἐπί</span> com genitivo do tribunal, ‘perante alguém’ (escólio sobre Hes., Op. 9), 24:21; 25:9; D 11:11.—<span class=\"greek\">τί</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀφ</span>’ <span class=\"greek\">ἑαυτῶν</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">κρίνετε</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">δίκαιον</span>;, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.57\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:57</a>, passagem que conduz ao âmbito da jurisprudência (v. 58), significa: por que não decidis por vós mesmos o que é justo? (compare a oração por vingança de Amorgos [BCH 25, 1901 p. 416; Dssm., LO 94 = LAE 118] <span class=\"greek\">ἐπάκουσον</span>, <span class=\"greek\">θεά</span>, <span class=\"greek\">καὶ</span> <span class=\"greek\">κρῖναι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">δίκαιον</span>; compare Appian, Mithrid. 89 §403 <span class=\"greek\">κρίνειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">μάχην</span>, decidir a batalha; Just., A II, 15, 5).</p>\n<p class=\"entry-text\"><span class=\"greek\">β</span>. Nas vozes média e passiva: ‘discutir, brigar, debater’, também recorrer à justiça (assim Thu. 4, 122, 4 <span class=\"greek\">δίκῃ</span> <span class=\"greek\">κρίνεσθαι</span>; Hos 2:4 e outras passagens na LXX; TestSol 4:4ff D; Mel., P. 101, 773), com <span class=\"greek\">τινί</span>, alguém (Job 9:3; 13:19), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:40</a>; B 6:1 (Is 50:8); <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span>, com alguém (Vi. Aesopi W 76 <span class=\"greek\">κριθῆναί</span> <span class=\"greek\">με</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κυρίας</span> <span class=\"greek\">μου</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">σοί</span>, estou defendendo minha causa contra minha senhora perante ti; Eccl 6:10), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:6</a>. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινος</span>, diante de alguém (como juiz), v. 1 (sobre o início de 1 Cor 6, compare o decreto de Alexandre aos gregos, em Ps.-Callisth. 2, 21, 21: <span class=\"greek\">βούλομαι</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑαυτοῖς</span> <span class=\"greek\">κρίνειν</span> <span class=\"greek\">ὅσον</span> <span class=\"greek\">τις</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἔχει</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἕτερον</span>, <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">οὗ</span> <span class=\"greek\">βούλεσθε</span>, é minha vontade que não litigueis entre vós, seja o que for que um tenha contra o outro, nem perante qualquer pessoa que desejardes).</p>\n<p class=\"entry-text\">ⓑ Do tribunal divino. <span class=\"greek\">α</span>. Presidido por Deus ou Cristo: absolutamente, administrar justiça, julgar, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.30\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:30</a>; 8:16, 50; compare v. 26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:10</a>; B 5:7. Na passiva: ser julgado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:1b</a>, 2b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:37b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:18</a>.—Seguido de acusativo (PGM 4, 1013, de Hórus, <span class=\"greek\">ὁ</span> <span class=\"greek\">κρίνων</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:22</a>; 8:15b. <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἔξω</span>, os de fora, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:13</a>. <span class=\"greek\">ζῶντας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">νεκρούς</span>, julgar vivos e mortos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:5</a>; B 7:2. <span class=\"greek\">τὰ</span> <span class=\"greek\">κρυπτὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνθρώπων</span>, os segredos das pessoas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:16</a>. <span class=\"greek\">τὸν</span> <span class=\"greek\">κόσμον</span>, o mundo, B 4:12 (TestAbr A 13 p. 92, 10 [Stone p. 32]; ApcEsdr 3:3 p. 27, 8 Tdf.). <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκουμένην</span>, a terra habitada, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:31</a>; AcPl Ha 9, 29. <span class=\"greek\">κ</span>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἑκάστου</span> <span class=\"greek\">ἔργον</span>, julgar cada um segundo aquilo que faz, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:17</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.20.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 20:13</a>. <span class=\"greek\">ἐκρίθησαν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">νεκροὶ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">γεγραμμένων</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">βιβλίοις</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔργα</span> <span class=\"greek\">αὐτῶν</span>, os mortos foram julgados conforme o que estava escrito nos livros (da vida e da morte), segundo suas obras, v. 12; <span class=\"greek\">δικαίως</span> <span class=\"greek\">κ</span>., julgar retamente (Sotades [280 a.C.] Fgm. 11, 2 Diehl2 II 6 p. 191 [em Stob. 4, 34, 8 vol. V p. 826, 5 = Coll. Alex. p. 243] <span class=\"greek\">ὁ</span> <span class=\"greek\">παντογενὴς</span> … <span class=\"greek\">οὐ</span> <span class=\"greek\">κρίνει</span> <span class=\"greek\">δικαίως</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:23</a>; B 19:11. Também <span class=\"greek\">ἐν</span> <span class=\"greek\">δικαιοσύνῃ</span>, com justiça, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:11</a>. <span class=\"greek\">διὰ</span> <span class=\"greek\">νόμου</span> <span class=\"greek\">κρίνεσθαι</span>, ser julgado com base na lei, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:12</a>.—Muitas vezes, o foco recai inconfundivelmente no que se segue à sentença do Juiz divino, ou seja, na condenação ou na punição: condenar, punir (em oposição a <span class=\"greek\">σῴζειν</span>, como TestJud 24:6; Mel., P. 104, 810; compare ApcEsdr 1, 11 p. 25, 3 Tdf. <span class=\"greek\">ἐμὲ</span> <span class=\"greek\">κρῖνον</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ψυχῶν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁμαρτωλῶν</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:17</a>; compare 18ab; 12:47ab, 48a; compare 48b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:7</a> (Gen 15:14); Dg 7:5f (em oposição a <span class=\"greek\">ἀγαπᾶν</span>). <span class=\"greek\">διὰ</span> <span class=\"greek\">νόμου</span> <span class=\"greek\">κ</span>., punir com base na lei, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:12</a>.—3:6f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.31\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:31f</a> (aqui a punição temporal imposta por Deus aos pecadores); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.30\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:30</a> (<span class=\"greek\">κρινεῖ</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λαὸν</span> <span class=\"greek\">αὐτοῦ</span>, o Senhor julgará, isto é, punirá seu povo, deriva de Dt 32:36 = Ps 134:14, que trata do julgamento divino, resultando na vindicação do inocente [ideia predominante nas duas passagens do AT] e na punição do culpado [ideia predominante na passagem de Hb]); 13:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:9</a>; quanto a <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:6</a>, veja 2a acima; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:8</a>; 19:2; B 15:5.—Com indicação da punição imposta: <span class=\"greek\">κ</span>. <span class=\"greek\">διὰ</span> <span class=\"greek\">πυρός</span>, julgar pelo fogo, 1 Cl 11:1; <span class=\"greek\">διὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">μαστίγων</span>, pelo açoite, 17:5. <span class=\"greek\">κεκριμένοι</span> <span class=\"greek\">ἤδη</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θανάτῳ</span>, já condenados à morte, B 10:5. Também <span class=\"greek\">εἰς</span> <span class=\"greek\">θάνατον</span>, condenados à morte, Hs 9, 18, 2. <span class=\"greek\">οἱ</span> <span class=\"greek\">κρινόμενοι</span> <span class=\"greek\">ἀσεβεῖς</span>, os ímpios que são condenados, 2 Cl 18:1. Do diabo: <span class=\"greek\">ὁ</span> <span class=\"greek\">ἄρχων</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span> <span class=\"greek\">τούτου</span> <span class=\"greek\">κέκριται</span>, o príncipe deste mundo já foi julgado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 16:11</a>.—<span class=\"greek\">ταῦτα</span> <span class=\"greek\">ἔκρινας</span>, impuseste esses castigos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:5</a>.—Sobre <span class=\"greek\">κρίνειν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κρίμα</span>, 18:20, veja <span class=\"greek\">κρίμα</span> 4.</p>\n<p class=\"entry-text\"><span class=\"greek\">β</span>. Presidido por pessoas divinamente comissionadas para julgar: os 12 apóstolos julgam as 12 tribos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:30</a> (PBatiffol, RB n.s. 9, 1912, 541–43. Aqui, porém, <span class=\"greek\">κ</span>. poderia ter o sentido mais amplo de governar; compare 4 Km 15:5; Ps 2:10; 1 Macc 9:73; PsSol 17:29). <span class=\"greek\">κρινεῖ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">φύσεως</span> <span class=\"greek\">ἀκροβυστία</span> … <span class=\"greek\">σέ</span>, aquele que é incircunciso por natureza te julgará, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:27</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">ἅγιοι</span>, os santos, como juízes do cosmos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:2ab</a> (<span class=\"greek\">κρίνεσθαι</span> <span class=\"greek\">ἐν</span>, Diod S 19, 51, 4.—Sobre os santos como corregentes de Deus, compare Epict., Ench. 15; Sallust. 21 p. 36, 14), e também dos anjos, v. 3 (compare Da 7:22).</p>\n<p class=\"entry-text\">⑥ Assegurar justiça a alguém, providenciar para que a justiça seja feita (LXX), com <span class=\"greek\">τινί</span>, para alguém, 1 Cl 8:4 (Is 1:17).—B. 1428. DELG. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0210-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κριός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κριός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (desde Hom.): carneiro, macho da ovelha, MPol 14:1 (veja <span class=\"greek\">ἐπίσημος</span> 1); B 2:4, variante de leitura (compare Is 1:11).—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0210-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρίσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κρίσις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (veja <span class=\"greek\">κρίνω</span>; Aeschyl., Hdt. e posteriores).</p>\n<p class=\"entry-text\">① Processo jurídico de julgamento; ato de julgar, julgamento.</p>\n<p class=\"entry-text\">ⓐ Da atuação de Deus ou do Messias como juiz, especialmente no Último Dia (Bacchylides 3, 26, de julgamento por Zeus).</p>\n<p class=\"entry-text\"><span class=\"greek\">α</span>. <span class=\"greek\">ἡ</span> <span class=\"greek\">δικαία</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, o justo julgamento de Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:5</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">κρίσις</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐμὴ</span> <span class=\"greek\">δικαία</span> <span class=\"greek\">ἐστίν</span>, o meu julgamento é justo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.30\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:30</a> (compare <span class=\"greek\">δικαία</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">κ</span>., Orig., C. Cels. 4, 9, 10). <span class=\"greek\">θεία</span> <span class=\"greek\">κ</span>., julgamento divino, 2 Cl 20:4. <span class=\"greek\">κρίσιν</span> <span class=\"greek\">ποιεῖν</span>, executar o julgamento, exercer a função de juiz (Aristoph., Ran. 778; 785; X., Hell. 4, 2, 6; 8; Dt 10:18.—Igualmente <span class=\"greek\">κ</span>. <span class=\"greek\">ποιεῖσθαι</span>: 1 Macc 6:22; Jos., Ant. 6, 34; Just., A I, 2, 3; D. 124, 1; Iren. 1, 10, 1 [Harv. I 91, 10]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.27\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:27</a>. <span class=\"greek\">τ</span>. <span class=\"greek\">κρίσιν</span> <span class=\"greek\">διδόναι</span> <span class=\"greek\">τινί</span>, conferir a alguém a função ou autoridade de julgar, v. 22 (TestAbr A 13 p. 92, 10 [Stone p. 32]). <span class=\"greek\">ἡ</span> <span class=\"greek\">ἡμέρα</span> (<span class=\"greek\">τῆς</span>) <span class=\"greek\">κρίσεως</span>, o Dia do Juízo (Jdth 16:17; Is 34:8; Pr 6:34; PsSol 15:12; GrBar 1:7; ApcEsdr 2:27 p. 26, 21 Tdf. e outras passagens; ApcMos 12:26; Just.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:15</a>; 11:22, 24; 12:36; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:11</a>, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:9</a>; 3:7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:17</a>; 2 Cl 16:3; 17:6; B 19:10; 21:6.—<span class=\"greek\">ἡ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἡ</span> <span class=\"greek\">μέλλουσα</span>, o juízo vindouro, 2 Cl 18:2; MPol 11:2. <span class=\"greek\">ἡ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐπερχομένη</span>, o julgamento iminente, Hv 3, 9, 5 (<span class=\"greek\">περὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐσομένης</span> <span class=\"greek\">κ</span>., Orig., C. Cels. 1, 56, 7; compare <span class=\"greek\">μετὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀνάστασιν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κ</span>., Theoph. Ant. 2, 26 [p. 164, 1]). Negação do Juízo Final, Pol 7:1. <span class=\"greek\">κ</span>. <span class=\"greek\">μεγάλης</span> <span class=\"greek\">ἡμέρας</span>, o juízo do Grande Dia, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Jd 6</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ὥρα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">αὐτοῦ</span>, a hora em que (Deus) julgará, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:7</a>. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀναστήσονται</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ἀσεβεῖς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κ</span>., os ímpios não se levantarão no julgamento (ou no Dia do Juízo), B 11:7 (Ps 1:5); compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:41f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:14</a>; 11:31f. <span class=\"greek\">δικαιοσύνη</span> <span class=\"greek\">κρίσεως</span> <span class=\"greek\">ἀρχὴ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τέλος</span>, a justiça (por parte do juiz) é o princípio e o fim do ato de julgar, B 1:6. O julgamento divino (compare Iambl., Vi. Pyth. 8, 40 <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀθανάτων</span> <span class=\"greek\">κ</span>.; Hierocles 11, 441 e 442 e outras ocorrências <span class=\"greek\">θεία</span> <span class=\"greek\">κρίσις</span>) é também mencionado em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.24\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.27\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:27</a> (compare Diog. L. 3, 79, com base em Platão: deve-se cumprir a <span class=\"greek\">δικαιοσύνη</span> <span class=\"greek\">θεοῦ</span>, <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θάνατον</span> <span class=\"greek\">δίκας</span> <span class=\"greek\">ὑπόσχοιεν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">κακοῦργοι</span>, para que os malfeitores não tenham de sofrer punições mesmo após a morte); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:4</a>, 9; 2 Cl 20:4; D 11:11.</p>\n<p class=\"entry-text\"><span class=\"greek\">β</span>. Frequentemente, a palavra significa julgamento desfavorável a alguém, condenação, e a pena consequente (TestAbr A 14 p. 93, 24 [Stone p. 34]; ApcEsdr 1:24 p. 25, 19 Tdf.; SibOr 3, 670; Just., D. 56, 1; 60, 2 <span class=\"greek\">κ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">Σοδόμων</span>), GPt 7:25. <span class=\"greek\">δισσὴν</span> <span class=\"greek\">ἕξουσιν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κ</span>., receberão dupla punição, 2 Cl 10:5. <span class=\"greek\">ἡ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">σου</span>, teu julgamento, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:10</a>. <span class=\"greek\">κἀκείνοις</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐστίν</span>, também sobre eles vem o juízo, ISm 6:1. <span class=\"greek\">φοβερά</span> <span class=\"greek\">τις</span> <span class=\"greek\">ἐκδοχὴ</span> <span class=\"greek\">κρίσεως</span>, terrível expectativa de julgamento, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.27\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:27</a> (Iambl., Vi. Pyth. 30, 179: a referência à <span class=\"greek\">κ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ψυχῶν</span> desperta <span class=\"greek\">φόβος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀδικίας</span>). <span class=\"greek\">ἡ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἤρθη</span>, sua punição foi removida, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:33</a>; 1 Cl 16:7 (ambos Is 53:8). <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">κρίσιν</span> <span class=\"greek\">πίπτειν</span>, cair sob juízo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:12</a>; compare 2:13ab. <span class=\"greek\">ἡ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">γεέννης</span>, ser castigado no inferno, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:33</a> (genitivo como em Diod S 1, 82, 3 <span class=\"greek\">θανάτου</span> <span class=\"greek\">κ</span>., punição por morte; <span class=\"greek\">πυρὸς</span> <span class=\"greek\">κ</span>., Hippol., Ref. 10, 34, 2; compare 9, 10, 7). <span class=\"greek\">ἔνοχός</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">αἰωνίου</span> <span class=\"greek\">κ</span>., sujeito a castigo eterno, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:29</a>, variante de leitura. <span class=\"greek\">κ</span>. <span class=\"greek\">κατά</span> <span class=\"greek\">τινος</span>, sobre ou contra alguém (Aelian, VH 2, 6); <span class=\"greek\">ποιῆσαι</span> <span class=\"greek\">κρίσιν</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">πάντων</span>, executar juízo contra todos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Jd 15</a> (En 1:9).—(Em oposição a <span class=\"greek\">ζωή</span>) <span class=\"greek\">ἔχει</span> <span class=\"greek\">ζωὴν</span> <span class=\"greek\">αἰώνιον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔρχεται</span>, tem vida eterna e não entra em juízo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:24</a> (compare Philip [=Demosth. 12, 16] <span class=\"greek\">εἰς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐλθεῖν</span>; ApcSed 11:16 [134, 36 Ja.] <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> … <span class=\"greek\">ἀπέρχεται</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">κρίσιν</span>). <span class=\"greek\">ἀνάστασις</span> <span class=\"greek\">ζωῆς</span> … <span class=\"greek\">ἀνάστασις</span> <span class=\"greek\">κρίσεως</span>, ressurreição da vida e ressurreição do julgamento, v. 29. <span class=\"greek\">κρίσις</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span> <span class=\"greek\">τούτου</span>, julgamento deste mundo (ou sobre este mundo), 12:31; compare 16:8, interpretado como juízo sobre o príncipe deste mundo, 16:11 (compare 12:31b; 1QM 1, 5; mas veja também LLutkemeyer, CBQ 8, ’46, 225f, ‘julgamento favorável’, e BNoack, Satanas u. Soteria ’48, 79; veja também <span class=\"greek\">δικαιοσύνη</span> 3a, final).—Alguns intérpretes encontram em 3:19 um duplo sentido de <span class=\"greek\">κ</span>., que, além de ‘julgamento’ e ‘condenação’, contém a clara conotação de ‘separação, divisão’ (Hecataeus [320 a.C.]: 264 Fgm. 6, 1 Jac. [em Diod S 40, 3, 2 Dind., segundo a tradição manuscrita] <span class=\"greek\">κρίσις</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">κακῶν</span>, ‘separação dos males’. Um duplo sentido como o de J aparece em Artem. 5, 5 <span class=\"greek\">κριτής</span>, ‘juiz’ e ‘divisor’). Diz-se que o ‘julgamento’, operante aqui e agora, consiste em que as pessoas se dividem em dois grupos: as que aceitam Cristo e as que o rejeitam (Hdb.; Bultmann). Mas também é provável que <span class=\"greek\">κ</span>. nesse versículo se refira simplesmente ao processo judicial, incluindo a exposição da razão ou fundamento do veredicto desfavorável, aqui expressa na oração <span class=\"greek\">ὅτι</span> … <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔργα</span>.—No plural, julgamentos, punições (Diod S 1, 75, 2; Appian, Bell. Civ. 1, 96 §446 <span class=\"greek\">κρίσεις</span> <span class=\"greek\">πικραί</span>, punições severas): <span class=\"greek\">ἀληθιναὶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">δίκαιαι</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">κρίσεις</span> <span class=\"greek\">σου</span>, verdadeiros e justos são os teus julgamentos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:7</a>; 19:2.—Bousset, Rel.3 257ff; LRuhl, De Mortuorum Judicio 1903; JBlank, Krisis (J), dissertação, Freiburg, ’64.</p>\n<p class=\"entry-text\">ⓑ Do julgamento proferido por uma pessoa sobre ou contra outra, sob a forma de avaliação. <span class=\"greek\">α</span>. De uma pessoa a respeito de outra: <span class=\"greek\">κ</span>. <span class=\"greek\">δικαία</span>, julgamento justo, B 20:2; D 5:2. <span class=\"greek\">κ</span>. <span class=\"greek\">ἄδικος</span>, juízo injusto, Pol 6:1; <span class=\"greek\">ἀπότομος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κ</span>., implacável ao julgar, na mesma passagem. <span class=\"greek\">τὴν</span> <span class=\"greek\">δικαίαν</span> <span class=\"greek\">κρίσιν</span> <span class=\"greek\">κρίνετε</span>, julgai com justo julgamento, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:24</a> (veja <span class=\"greek\">κρίνω</span> 2a). Compare <span class=\"greek\">ἡ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐμὴ</span> <span class=\"greek\">ἀληθινή</span> <span class=\"greek\">ἐστιν</span>, o meu julgamento é verdadeiro, 8:16.</p>\n<p class=\"entry-text\"><span class=\"greek\">β</span>. Do arcanjo contra o diabo: <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐτόλμησεν</span> <span class=\"greek\">κρίσιν</span> <span class=\"greek\">ἐπενεγκεῖν</span> <span class=\"greek\">βλασφημίας</span>, não ousou proferir sentença injuriosa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Jd 9</a>. Compare a passagem correspondente em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:11</a>: <span class=\"greek\">ἄγγελοι</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">φέρουσιν</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">βλάσφημον</span> <span class=\"greek\">κρίσιν</span>, anjos não apresentam contra eles, da parte do Senhor, juízo injurioso.</p>\n<p class=\"entry-text\">② Um corpo de juízes; tribunal, especificamente tribunal local (veja Schürer II 187f; Diod S 17, 80, 2; Aesop, Fab. 190 H. = 459 P.; Theod. Prodr. 1, 402 H.): <span class=\"greek\">ἔνοχος</span> <span class=\"greek\">ἔσται</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">κ</span>., estará sujeito ao julgamento de um tribunal (local), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:21f</a>.—RGuelich, ZNW 64, ’73, 44ff.</p>\n<p class=\"entry-text\">③ Administração daquilo que é correto e equitativo; direito, no sentido de justiça, retidão (Michel 542, 6 [II a.C.] <span class=\"greek\">πίστιν</span> <span class=\"greek\">ἔχοντα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κρίσιν</span> <span class=\"greek\">ὑγιῆ</span>; OGI 383, 207 [I a.C.]; LXX; compare <span class=\"hebrew\" dir=\"rtl\">מִשְׁפָּט</span>): <span class=\"greek\">ἀφήκατε</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κρίσιν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔλεος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πίστιν</span>, negligenciastes a justiça, a misericórdia e a fidelidade, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:23</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:42</a>. <span class=\"greek\">ἐκζητεῖν</span> <span class=\"greek\">κ</span>., buscar a justiça, 1 Cl 8:4 (Is 1:17). <span class=\"greek\">κρίσιν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἔθνεσιν</span> <span class=\"greek\">ἀπαγγελεῖ</span>, anunciará justiça aos gentios, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:18</a> (Is 42:1). <span class=\"greek\">ἕως</span> <span class=\"greek\">ἃν</span> <span class=\"greek\">ἐκβάλῃ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">νῖκος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κρίσιν</span>, até que conduza a justiça à vitória, v. 20 (compare Is 42:3.—Outras traduções possíveis são ação judicial, processo, causa [X., An. 1, 6, 5; Diod S 2, 42, 4 <span class=\"greek\">αἱ</span> <span class=\"greek\">κρίσεις</span>, litígios, transações; En 9:3 <span class=\"greek\">εἰσαγάγετε</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κρίσιν</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ὕψιστον</span>] e, sob influência de <span class=\"greek\">νῖκος</span>, uma decisão [militar] [Dionys. Hal. 9, 35; 2 Macc 14:18]). A tradução direito, justiça também pode ser apropriada para passagens como <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:24</a>; 12:31; 16:8, 11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:33</a> [assim NRSV] e talvez outras.—GWetter, veja <span class=\"greek\">κρίμα</span> 4b, perto do final; HBraun, Gerichtsgedanke u. Rechtfertigungslehre b. Pls 1930; FFilson, St. Paul’s Conception of Recompense ’31.—Para outras referências sobre o tema da justiça na Antiguidade, veja PvanderHorst, The Sentences of Pseudo-Phocylides 78, 117–28.—DELG s.v. <span class=\"greek\">κρίνω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0210-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρίσμα</h1><div class=\"entry-meta\"><span>remissão lexical</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κρίσμα</span>: veja <span class=\"greek\">κρίμα</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0210-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κρίσπος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Κρίσπος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (também <span class=\"greek\">Κρῖσπος</span>; Diod S 15, 38, 1; Crinagoras no. 48, 2; inscrições, papiros; Jos., Vi. 33; quanto ao acento, veja B-D-F §41, 3; Rob. 235): Crispo, dirigente da sinagoga em Corinto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:8</a>; batizado por Paulo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:14</a>. Como variante de leitura (Syr., Goth.) em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:10</a>. BHHW II, 1014; Haenchen ad loc.—LGPN I. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0210-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κριτήριον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κριτήριον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (veja <span class=\"greek\">κρίνω</span>; desde Pla.): originalmente ‘meio de julgar ou provar, um critério’. Nem essa acepção nem a de ‘julgamento’ (como em SEG XXXVIII, 1224, 16) ocorrem no NT.</p>\n<p class=\"entry-text\">① Foro para administrar a justiça; tribunal, juízo (assim desde Pla., Leg. 6, 767b, também Polyb.; Diod S; SIG 683, 48; 807, 9; UPZ 118, 15; PHib 29 = Mitt-Wilck. I/2, 259, 5; BGU 1054, 1; LXX; TestAbr; ApcEsdr 2:30 p. 26, 24 Tdf. e outros; compare Philo, Virt. 66). <span class=\"greek\">ἕλκειν</span> <span class=\"greek\">τινὰ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">κριτήρια</span>, arrastar alguém aos tribunais, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:6</a> (compare PTurin I, 1 VI, 11 [117 a.C.] <span class=\"greek\">ἑλκυσθέντων</span> <span class=\"greek\">ἁπάντων</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κριτήριον</span>). <span class=\"greek\">ἔστη</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>., (Maria) apresentou-se diante do tribunal (dos sacerdotes), GJs 15:2; [<span class=\"greek\">ἀπ</span>] <span class=\"greek\">ήγαγον</span> <span class=\"greek\">αὐτὴν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>., levaram-na ao tribunal, 15:2, variante de leitura. Esta acepção pode estar por trás de duas outras passagens da nossa literatura com <span class=\"greek\">κ</span>.: <span class=\"greek\">ἀνάξιοί</span> <span class=\"greek\">ἐστε</span> <span class=\"greek\">κριτηρίων</span> <span class=\"greek\">ἐλαχίστων</span>;, talvez signifique: sois incapazes de constituir até mesmo tribunais insignificantes (isto é, com jurisdição sobre questões pequenas da vida cotidiana)?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:2</a>. Igualmente <span class=\"greek\">βιωτικὰ</span> <span class=\"greek\">κριτήρια</span> <span class=\"greek\">ἐὰν</span> <span class=\"greek\">ἔχητε</span>, <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἐξουθενημένους</span> <span class=\"greek\">καθίζετε</span>;, se necessitais de tribunais para as questões da vida cotidiana, designais pessoas desprezadas (como juízes)?, v. 4 (<span class=\"greek\">καθίζειν</span> <span class=\"greek\">κριτήριον</span>, como Polyb. 9, 33, 12). Contudo, em ambos os casos predomina a preferência, para <span class=\"greek\">κ</span>., pelo sentido</p>\n<p class=\"entry-text\">② Causa submetida a tribunal; processo, demanda judicial (por exemplo, JWeiss, Ltzm., Sickenberger, H-DWendland). Compare Cyr. Ins. ln. 21 <span class=\"greek\">θανατηφόρα</span> <span class=\"greek\">κριτήρια</span>, processos que envolvem pena capital (correspondente ao latim judicia capitis); SEG VIII, 13 (= <span class=\"greek\">Διάταγμα</span> <span class=\"greek\">Καίσαρος</span> [I d.C.]; Boffo, Iscrizioni no. 39 [bibliografia]) ln. 14 <span class=\"greek\">κριτήριον</span> <span class=\"greek\">γενέσθαι</span>, que a demanda seja julgada. Igualmente Diod S 1, 72, 4; 36, 3, 3.—New Docs 4, 157 (referência Pfuhl-Möbius = SEG acima). DELG s.v. <span class=\"greek\">κρίνω</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0210-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κριτής, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κριτής</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (veja <span class=\"greek\">κρίνω</span>; autores trágicos, Hdt. e posteriores; empréstimo no hebraico rabínico): ‘aquele que chega a uma decisão ou profere um julgamento’.</p>\n<p class=\"entry-text\">① Pessoa que tem direito de decidir matérias jurídicas; juiz.</p>\n<p class=\"entry-text\">ⓐ Literalmente, na jurisprudência (não no grego mais antigo nesse sentido, mas Diod S 1, 92, 4; Epict. 3, 7, 30; inscrições; POxy 97, 5; 726, 20; 1195, 1; PTebt 317, 20; LXX). <span class=\"greek\">α</span>. De seres humanos: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:14</a>, 58; 18:2. <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀδικίας</span>, o juiz injusto, 18:6 (quanto ao genitivo, veja <span class=\"greek\">ἀδικία</span> 2, final; W-S. §30, 8; Mlt-H. 440; JDerrett, NTS 18, ’71/72, 178–91). <span class=\"greek\">πενήτων</span> <span class=\"greek\">ἄνομοι</span> <span class=\"greek\">κ</span>., juízes dos pobres que agem sem lei, B 20:2; D 5:2. Dos juízes de Herodes Antipas, GPt 1:1. Do procurador, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:10</a> (variante de leitura <span class=\"greek\">κ</span>. <span class=\"greek\">δίκαιος</span>; assim, de um juiz humano, Epict., Gnomolog. 48; ApcrEzk [Denis p. 122 ln. 4 = Epiph., Haer. 70, 15]). Do procônsul: <span class=\"greek\">κ</span>. <span class=\"greek\">τούτων</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">βούλομαι</span> <span class=\"greek\">εἶναι</span>, não quero ser juiz dessas questões, 18:15.</p>\n<p class=\"entry-text\"><span class=\"greek\">β</span>. De Deus (LXX; Philo; Jos., Bell. 5, 390; TestJud 20:5; PsSol 4:24 e outros; Did., Gen. 233, 5; compare Iren. 1, 13, 6 [Harv. I 124, 1]. Compare Ael. Aristid. 13 p. 230 D.: <span class=\"greek\">τὶς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">οὐρανοῦ</span> <span class=\"greek\">κριτής</span>) e de Cristo (Iren. 3, 12, 9 [Harv. II 63, 8]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.23\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:12</a>; <span class=\"greek\">δίκαιος</span> <span class=\"greek\">κ</span>., justo juiz, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:8</a>; Hs 6, 3, 6 (PsSol 2:18 e outros). De Deus ou de Cristo: <span class=\"greek\">κ</span>. <span class=\"greek\">ζώντων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">νεκρῶν</span>, juiz dos vivos e dos mortos, 2 Cl 1:1.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.42\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:42</a>; Pol 2:1. <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">πρὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">θυρῶν</span> <span class=\"greek\">ἕστηκεν</span>, o juiz está às portas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:9</a>.</p>\n<p class=\"entry-text\">ⓑ Em sentido mais amplo (Appian, Liby. 52 §227 <span class=\"greek\">κριτής</span> <span class=\"greek\">τινος</span>, juiz ou crítico de alguma coisa): <span class=\"greek\">κριταὶ</span> <span class=\"greek\">διαλογισμῶν</span> <span class=\"greek\">πονηρῶν</span>, juízes com pensamentos maus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:4</a>; Tat. 23, 2, de espectadores de combates de gladiadores. <span class=\"greek\">κριτὴς</span> (<span class=\"greek\">νόμου</span>), juiz (da lei), 4:11. Dos ‘filhos’ dos fariseus: <span class=\"greek\">κριταὶ</span> <span class=\"greek\">ἔσονται</span> <span class=\"greek\">ὑμῶν</span>, serão vossos juízes, isto é, condenar-vos-ão por vossa conduta errada, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:19</a>. De Moisés, 1 Cl 4:10, variante de leitura (compare Ex 2:14).</p>\n<p class=\"entry-text\">② Quem governa em sentido particular nas narrativas do período teocrático de Israel; governante, tradicionalmente traduzido por juiz, líder do povo no período anterior ao surgimento da monarquia hebraica (compare Judg 2:16, 18f; Ruth 1:1; Jos., Ant. 6, 85; 11, 112), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:20</a>.—DELG s.v. <span class=\"greek\">κρίνω</span>. M-M. TW.</p></section></article>"};
